// 获取当前时间，并设置为北京时间（东八区）
const now = new Date();
const today = new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()));
const yesterday = new Date(today);
yesterday.setDate(yesterday.getDate() - 1);

// 输出为 YYYY-MM-DD 格式的字符串（与表格中的文本格式一致）
const todayString = today.toISOString().split('T')[0];
const yesterdayString = yesterday.toISOString().split('T')[0];

return [
  {
    json: {
      todayString: todayString,      // 例如 "2026-08-04"
      yesterdayString: yesterdayString // 例如 "2026-08-03"
    }
  }
];

// 获取当前时间
const now = new Date();

// 1. 计算今天的开始时间 (00:00:00) - 使用 UTC 避免时区问题
const todayStart = new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()));
// 转为秒级时间戳（10位），并确保是字符串
const start_time = String(Math.floor(todayStart.getTime() / 1000));

// 2. 计算7天后的结束时间 (23:59:59)
const futureDate = new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate() + 7));
// 注意：上面直接加7天，但要确保时间设到当天结束
const endDate = new Date(futureDate);
endDate.setUTCHours(23, 59, 59, 999);
const end_time = String(Math.floor(endDate.getTime() / 1000));

// 返回结果
return {
  start_time: start_time,
  end_time: end_time
};
